boolean SessionIDType_template::match(const SessionIDType& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.content().is_bound()) return FALSE;
if((other_value.content().ispresent() ? !single_value->field_content.match((const OCTETSTRING&)other_value.content(), legacy) : !single_value->field_content.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.SessionIDType.");
}
return FALSE;
}

boolean SessionIDType_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return (single_value->field_content.is_omit() || single_value->field_content.is_bound())
;
}

boolean SessionIDType_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return (single_value->field_content.is_omit() || single_value->field_content.is_value());
}

void SessionIDType_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

SessionIDType SessionIDType_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.SessionIDType.");
SessionIDType ret_val;
if (single_value->field_content.is_omit()) ret_val.content() = OMIT_VALUE;
else if (single_value->field_content.is_bound()) {
ret_val.content() = single_value->field_content.valueof();
}
return ret_val;
}

void SessionIDType_template::set_type(template_sel template_type, unsigned int list_length)
{
if (template_type != VALUE_LIST && template_type != COMPLEMENTED_LIST)
TTCN_error("Setting an invalid list for a template of type @SECC_Types.SessionIDType.");
clean_up();
set_selection(template_type);
value_list.n_values = list_length;
value_list.list_value = new SessionIDType_template[list_length];
}

SessionIDType_template& SessionIDType_template::list_item(unsigned int list_index) const
{
if (template_selection != VALUE_LIST && template_selection != COMPLEMENTED_LIST)
TTCN_error("Accessing a list element of a non-list template of type @SECC_Types.SessionIDType.");
if (list_index >= value_list.n_values)
TTCN_error("Index overflow in a value list template of type @SECC_Types.SessionIDType.");
return value_list.list_value[list_index];
}

