void AppProtocolEntry_template::copy_value(const AppProtocolEntry& other_value)
{
single_value = new single_value_struct;
if (other_value.protocolNamespace().is_bound()) {
  single_value->field_protocolNamespace = other_value.protocolNamespace();
} else {
  single_value->field_protocolNamespace.clean_up();
}
if (other_value.versionNumberMajor().is_bound()) {
  single_value->field_versionNumberMajor = other_value.versionNumberMajor();
} else {
  single_value->field_versionNumberMajor.clean_up();
}
if (other_value.versionNumberMinor().is_bound()) {
  single_value->field_versionNumberMinor = other_value.versionNumberMinor();
} else {
  single_value->field_versionNumberMinor.clean_up();
}
if (other_value.SchemaID().is_bound()) {
  if (other_value.SchemaID().ispresent()) single_value->field_SchemaID = other_value.SchemaID()();
  else single_value->field_SchemaID = OMIT_VALUE;
} else {
  single_value->field_SchemaID.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void AppProtocolEntry_template::copy_template(const AppProtocolEntry_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.protocolNamespace().get_selection()) {
single_value->field_protocolNamespace = other_value.protocolNamespace();
} else {
single_value->field_protocolNamespace.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.versionNumberMajor().get_selection()) {
single_value->field_versionNumberMajor = other_value.versionNumberMajor();
} else {
single_value->field_versionNumberMajor.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.versionNumberMinor().get_selection()) {
single_value->field_versionNumberMinor = other_value.versionNumberMinor();
} else {
single_value->field_versionNumberMinor.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.SchemaID().get_selection()) {
single_value->field_SchemaID = other_value.SchemaID();
} else {
single_value->field_SchemaID.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new AppProtocolEntry_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.AppProtocolEntry.");
break;
}
set_selection(other_value);
}

