boolean AppProtocolEntry_template::match(const AppProtocolEntry& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.protocolNamespace().is_bound()) return FALSE;
if(!single_value->field_protocolNamespace.match(other_value.protocolNamespace(), legacy))return FALSE;
if(!other_value.versionNumberMajor().is_bound()) return FALSE;
if(!single_value->field_versionNumberMajor.match(other_value.versionNumberMajor(), legacy))return FALSE;
if(!other_value.versionNumberMinor().is_bound()) return FALSE;
if(!single_value->field_versionNumberMinor.match(other_value.versionNumberMinor(), legacy))return FALSE;
if(!other_value.SchemaID().is_bound()) return FALSE;
if((other_value.SchemaID().ispresent() ? !single_value->field_SchemaID.match((const INTEGER&)other_value.SchemaID(), legacy) : !single_value->field_SchemaID.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.AppProtocolEntry.");
}
return FALSE;
}

boolean AppProtocolEntry_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return single_value->field_protocolNamespace.is_bound()

 ||single_value->field_versionNumberMajor.is_bound()

 ||single_value->field_versionNumberMinor.is_bound()

 ||(single_value->field_SchemaID.is_omit() || single_value->field_SchemaID.is_bound())
;
}

boolean AppProtocolEntry_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return single_value->field_protocolNamespace.is_value()
 &&single_value->field_versionNumberMajor.is_value()
 &&single_value->field_versionNumberMinor.is_value()
 &&(single_value->field_SchemaID.is_omit() || single_value->field_SchemaID.is_value());
}

void AppProtocolEntry_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

