boolean SupportedAppProtocolReq_template::match(const SupportedAppProtocolReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.protocolArray().is_bound()) return FALSE;
if((other_value.protocolArray().ispresent() ? !single_value->field_protocolArray.match((const SupportedAppProtocolReq_protocolArray&)other_value.protocolArray(), legacy) : !single_value->field_protocolArray.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.SupportedAppProtocolReq.");
}
return FALSE;
}

boolean SupportedAppProtocolReq_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return (single_value->field_protocolArray.is_omit() || single_value->field_protocolArray.is_bound())
;
}

