struct SupportedAppProtocolRes_template::single_value_struct {
INTEGER_template field_ResponseCode;
INTEGER_template field_SchemaID;
CHARSTRING_template field_SchemaURI;
};

void SupportedAppProtocolRes_template::set_specific()
{
if (template_selection != SPECIFIC_VALUE) {
template_sel old_selection = template_selection;
clean_up();
single_value = new single_value_struct;
set_selection(SPECIFIC_VALUE);
if (old_selection == ANY_VALUE || old_selection == ANY_OR_OMIT) {
single_value->field_ResponseCode = ANY_VALUE;
single_value->field_SchemaID = ANY_OR_OMIT;
single_value->field_SchemaURI = ANY_OR_OMIT;
}
}
}

void SupportedAppProtocolRes_template::copy_value(const SupportedAppProtocolRes& other_value)
{
single_value = new single_value_struct;
if (other_value.ResponseCode().is_bound()) {
  single_value->field_ResponseCode = other_value.ResponseCode();
} else {
  single_value->field_ResponseCode.clean_up();
}
if (other_value.SchemaID().is_bound()) {
  if (other_value.SchemaID().ispresent()) single_value->field_SchemaID = other_value.SchemaID()();
  else single_value->field_SchemaID = OMIT_VALUE;
} else {
  single_value->field_SchemaID.clean_up();
}
if (other_value.SchemaURI().is_bound()) {
  if (other_value.SchemaURI().ispresent()) single_value->field_SchemaURI = other_value.SchemaURI()();
  else single_value->field_SchemaURI = OMIT_VALUE;
} else {
  single_value->field_SchemaURI.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void SupportedAppProtocolRes_template::copy_template(const SupportedAppProtocolRes_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.ResponseCode().get_selection()) {
single_value->field_ResponseCode = other_value.ResponseCode();
} else {
single_value->field_ResponseCode.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.SchemaID().get_selection()) {
single_value->field_SchemaID = other_value.SchemaID();
} else {
single_value->field_SchemaID.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.SchemaURI().get_selection()) {
single_value->field_SchemaURI = other_value.SchemaURI();
} else {
single_value->field_SchemaURI.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new SupportedAppProtocolRes_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.SupportedAppProtocolRes.");
break;
}
set_selection(other_value);
}

