int SupportedAppProtocolRes_template::size_of() const
{
  if (is_ifpresent) TTCN_error("Performing sizeof() operation on a template of type @SECC_Types.SupportedAppProtocolRes which has an ifpresent attribute.");
  switch (template_selection)
  {
  case SPECIFIC_VALUE:
  {    int ret_val = 1;
      if (single_value->field_SchemaID.is_present()) ret_val++;
      if (single_value->field_SchemaURI.is_present()) ret_val++;
      return ret_val;
    }
  case VALUE_LIST:
   {
     if (value_list.n_values<1)
       TTCN_error("Internal error: Performing sizeof() operation on a template of type @SECC_Types.SupportedAppProtocolRes containing an empty list.");
      int item_size = value_list.list_value[0].size_of();
      for (unsigned int l_idx = 1; l_idx < value_list.n_values; l_idx++)
      {
        if (value_list.list_value[l_idx].size_of()!=item_size)
          TTCN_error("Performing sizeof() operation on a template of type @SECC_Types.SupportedAppProtocolRes containing a value list with different sizes.");
      }
      return item_size;
    }
  case OMIT_VALUE:
    TTCN_error("Performing sizeof() operation on a template of type @SECC_Types.SupportedAppProtocolRes containing omit value.");
  case ANY_VALUE:
  case ANY_OR_OMIT:
    TTCN_error("Performing sizeof() operation on a template of type @SECC_Types.SupportedAppProtocolRes containing */? value.");
  case COMPLEMENTED_LIST:
    TTCN_error("Performing sizeof() operation on a template of type @SECC_Types.SupportedAppProtocolRes containing complemented list.");
  default:
    TTCN_error("Performing sizeof() operation on an uninitialized/unsupported template of type @SECC_Types.SupportedAppProtocolRes.");
  }
  return 0;
}

void SupportedAppProtocolRes_template::log() const
{
switch (template_selection) {
case SPECIFIC_VALUE:
TTCN_Logger::log_event_str("{ ResponseCode := ");
single_value->field_ResponseCode.log();
TTCN_Logger::log_event_str(", SchemaID := ");
single_value->field_SchemaID.log();
TTCN_Logger::log_event_str(", SchemaURI := ");
single_value->field_SchemaURI.log();
TTCN_Logger::log_event_str(" }");
break;
case COMPLEMENTED_LIST:
TTCN_Logger::log_event_str("complement");
case VALUE_LIST:
TTCN_Logger::log_char('(');
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++) {
if (list_count > 0) TTCN_Logger::log_event_str(", ");
value_list.list_value[list_count].log();
}
TTCN_Logger::log_char(')');
break;
default:
log_generic();
}
log_ifpresent();
}

void SupportedAppProtocolRes_template::log_match(const SupportedAppProtocolRes& match_value, boolean legacy) const
{
if(TTCN_Logger::VERBOSITY_COMPACT == TTCN_Logger::get_matching_verbosity()){
if(match(match_value, legacy)){
TTCN_Logger::print_logmatch_buffer();
TTCN_Logger::log_event_str(" matched");
} else{
if (template_selection == SPECIFIC_VALUE) {
size_t previous_size = TTCN_Logger::get_logmatch_buffer_len();
if(!single_value->field_ResponseCode.match(match_value.ResponseCode(), legacy)){
TTCN_Logger::log_logmatch_info(".ResponseCode");
single_value->field_ResponseCode.log_match(match_value.ResponseCode(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
if (match_value.SchemaID().ispresent()){
if(!single_value->field_SchemaID.match(match_value.SchemaID(), legacy)){
TTCN_Logger::log_logmatch_info(".SchemaID");
single_value->field_SchemaID.log_match(match_value.SchemaID(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
} else {
if (!single_value->field_SchemaID.match_omit(legacy)){
 TTCN_Logger::log_logmatch_info(".SchemaID := omit with ");
TTCN_Logger::print_logmatch_buffer();
single_value->field_SchemaID.log();
TTCN_Logger::log_event_str(" unmatched");
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}
if (match_value.SchemaURI().ispresent()){
if(!single_value->field_SchemaURI.match(match_value.SchemaURI(), legacy)){
TTCN_Logger::log_logmatch_info(".SchemaURI");
single_value->field_SchemaURI.log_match(match_value.SchemaURI(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
} else {
if (!single_value->field_SchemaURI.match_omit(legacy)){
 TTCN_Logger::log_logmatch_info(".SchemaURI := omit with ");
TTCN_Logger::print_logmatch_buffer();
single_value->field_SchemaURI.log();
TTCN_Logger::log_event_str(" unmatched");
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}
}else {
TTCN_Logger::print_logmatch_buffer();
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
TTCN_Logger::log_event_str(" unmatched");
}
}
return;
}
if (template_selection == SPECIFIC_VALUE) {
TTCN_Logger::log_event_str("{ ResponseCode := ");
single_value->field_ResponseCode.log_match(match_value.ResponseCode(), legacy);
TTCN_Logger::log_event_str(", SchemaID := ");
if (match_value.SchemaID().ispresent()) single_value->field_SchemaID.log_match(match_value.SchemaID(), legacy);
else {
TTCN_Logger::log_event_str("omit with ");
single_value->field_SchemaID.log();
if (single_value->field_SchemaID.match_omit(legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
TTCN_Logger::log_event_str(", SchemaURI := ");
if (match_value.SchemaURI().ispresent()) single_value->field_SchemaURI.log_match(match_value.SchemaURI(), legacy);
else {
TTCN_Logger::log_event_str("omit with ");
single_value->field_SchemaURI.log();
if (single_value->field_SchemaURI.match_omit(legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
TTCN_Logger::log_event_str(" }");
} else {
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
if (match(match_value, legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
}

void SupportedAppProtocolRes_template::encode_text(Text_Buf& text_buf) const
{
encode_text_base(text_buf);
switch (template_selection) {
case SPECIFIC_VALUE:
single_value->field_ResponseCode.encode_text(text_buf);
single_value->field_SchemaID.encode_text(text_buf);
single_value->field_SchemaURI.encode_text(text_buf);
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
text_buf.push_int(value_list.n_values);
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].encode_text(text_buf);
break;
default:
TTCN_error("Text encoder: Encoding an uninitialized/unsupported template of type @SECC_Types.SupportedAppProtocolRes.");
}
}

void SupportedAppProtocolRes_template::decode_text(Text_Buf& text_buf)
{
clean_up();
decode_text_base(text_buf);
switch (template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
single_value->field_ResponseCode.decode_text(text_buf);
single_value->field_SchemaID.decode_text(text_buf);
single_value->field_SchemaURI.decode_text(text_buf);
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = text_buf.pull_int().get_val();
value_list.list_value = new SupportedAppProtocolRes_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].decode_text(text_buf);
break;
default:
TTCN_error("Text decoder: An unknown/unsupported selection was received in a template of type @SECC_Types.SupportedAppProtocolRes.");
}
}

void SupportedAppProtocolRes_template::set_param(Module_Param& param)
{
  param.basic_check(Module_Param::BC_TEMPLATE, "record template");
  switch (param.get_type()) {
  case Module_Param::MP_Omit:
    *this = OMIT_VALUE;
    break;
  case Module_Param::MP_Any:
    *this = ANY_VALUE;
    break;
  case Module_Param::MP_AnyOrNone:
    *this = ANY_OR_OMIT;
    break;
  case Module_Param::MP_List_Template:
  case Module_Param::MP_ComplementList_Template: {
    SupportedAppProtocolRes_template new_temp;
    new_temp.set_type(param.get_type()==Module_Param::MP_List_Template ? VALUE_LIST : COMPLEMENTED_LIST, param.get_size());
    for (size_t p_i=0; p_i<param.get_size(); p_i++) {
      new_temp.list_item(p_i).set_param(*param.get_elem(p_i));
    }
    *this = new_temp;
    break; }
  case Module_Param::MP_Value_List:
    if (3<param.get_size()) {
      param.error("record template of type @SECC_Types.SupportedAppProtocolRes has 3 fields but list value has %d fields", (int)param.get_size());
    }
    if (param.get_size()>0 && param.get_elem(0)->get_type()!=Module_Param::MP_NotUsed) ResponseCode().set_param(*param.get_elem(0));
    if (param.get_size()>1 && param.get_elem(1)->get_type()!=Module_Param::MP_NotUsed) SchemaID().set_param(*param.get_elem(1));
    if (param.get_size()>2 && param.get_elem(2)->get_type()!=Module_Param::MP_NotUsed) SchemaURI().set_param(*param.get_elem(2));
    break;
  case Module_Param::MP_Assignment_List: {
    Vector<bool> value_used(param.get_size());
    value_used.resize(param.get_size(), FALSE);
    for (size_t val_idx=0; val_idx<param.get_size(); val_idx++) {
      Module_Param* const curr_param = param.get_elem(val_idx);
      if (!strcmp(curr_param->get_id()->get_name(), "ResponseCode")) {
        if (curr_param->get_type()!=Module_Param::MP_NotUsed) {
          ResponseCode().set_param(*curr_param);
        }
        value_used[val_idx]=TRUE;
      }
    }
    for (size_t val_idx=0; val_idx<param.get_size(); val_idx++) {
      Module_Param* const curr_param = param.get_elem(val_idx);
      if (!strcmp(curr_param->get_id()->get_name(), "SchemaID")) {
        if (curr_param->get_type()!=Module_Param::MP_NotUsed) {
          SchemaID().set_param(*curr_param);
        }
        value_used[val_idx]=TRUE;
      }
    }
    for (size_t val_idx=0; val_idx<param.get_size(); val_idx++) {
      Module_Param* const curr_param = param.get_elem(val_idx);
      if (!strcmp(curr_param->get_id()->get_name(), "SchemaURI")) {
        if (curr_param->get_type()!=Module_Param::MP_NotUsed) {
          SchemaURI().set_param(*curr_param);
        }
        value_used[val_idx]=TRUE;
      }
    }
    for (size_t val_idx=0; val_idx<param.get_size(); val_idx++) if (!value_used[val_idx]) {
      Module_Param* const curr_param = param.get_elem(val_idx);
      curr_param->error("Non existent field name in type @SECC_Types.SupportedAppProtocolRes: %s", curr_param->get_id()->get_name());
      break;
    }
  } break;
  default:
    param.type_error("record template", "@SECC_Types.SupportedAppProtocolRes");
  }
  is_ifpresent = param.get_ifpresent();
}

void SupportedAppProtocolRes_template::check_restriction(template_res t_res, const char* t_name, boolean legacy) const
{
if (template_selection==UNINITIALIZED_TEMPLATE) return;
switch ((t_name&&(t_res==TR_VALUE))?TR_OMIT:t_res) {
case TR_OMIT:
if (template_selection==OMIT_VALUE) return;
case TR_VALUE:
if (template_selection!=SPECIFIC_VALUE || is_ifpresent) break;
single_value->field_ResponseCode.check_restriction(t_res, t_name ? t_name : "@SECC_Types.SupportedAppProtocolRes");
single_value->field_SchemaID.check_restriction(t_res, t_name ? t_name : "@SECC_Types.SupportedAppProtocolRes");
single_value->field_SchemaURI.check_restriction(t_res, t_name ? t_name : "@SECC_Types.SupportedAppProtocolRes");
return;
case TR_PRESENT:
if (!match_omit(legacy)) return;
break;
default:
return;
}
TTCN_error("Restriction `%s' on template of type %s violated.", get_res_name(t_res), t_name ? t_name : "@SECC_Types.SupportedAppProtocolRes");
}

boolean SupportedAppProtocolRes_template::is_present(boolean legacy) const
{
if (template_selection==UNINITIALIZED_TEMPLATE) return FALSE;
return !match_omit(legacy);
}

boolean SupportedAppProtocolRes_template::match_omit(boolean legacy) const
{
if (is_ifpresent) return TRUE;
switch (template_selection) {
case OMIT_VALUE:
case ANY_OR_OMIT:
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
if (legacy) {
for (unsigned int l_idx=0; l_idx<value_list.n_values; l_idx++)
if (value_list.list_value[l_idx].match_omit())
return template_selection==VALUE_LIST;
return template_selection==COMPLEMENTED_LIST;
} // else fall through
default:
return FALSE;
}
return FALSE;
}

