boolean SessionSetupReq_template::match(const SessionSetupReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.EVCCID().is_bound()) return FALSE;
if(!single_value->field_EVCCID.match(other_value.EVCCID(), legacy))return FALSE;
if(!other_value.DEXArray().is_bound()) return FALSE;
if((other_value.DEXArray().ispresent() ? !single_value->field_DEXArray.match((const SessionSetupReq_DEXArray&)other_value.DEXArray(), legacy) : !single_value->field_DEXArray.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.SessionSetupReq.");
}
return FALSE;
}

boolean SessionSetupReq_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return single_value->field_EVCCID.is_bound()

 ||(single_value->field_DEXArray.is_omit() || single_value->field_DEXArray.is_bound())
;
}

boolean SessionSetupReq_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return single_value->field_EVCCID.is_value()
 &&(single_value->field_DEXArray.is_omit() || single_value->field_DEXArray.is_value());
}

void SessionSetupReq_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

SessionSetupReq SessionSetupReq_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.SessionSetupReq.");
SessionSetupReq ret_val;
if (single_value->field_EVCCID.is_bound()) {
ret_val.EVCCID() = single_value->field_EVCCID.valueof();
}
if (single_value->field_DEXArray.is_omit()) ret_val.DEXArray() = OMIT_VALUE;
else if (single_value->field_DEXArray.is_bound()) {
ret_val.DEXArray() = single_value->field_DEXArray.valueof();
}
return ret_val;
}

