void SessionSetupRes_template::copy_template(const SessionSetupRes_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.ResponseCode().get_selection()) {
single_value->field_ResponseCode = other_value.ResponseCode();
} else {
single_value->field_ResponseCode.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EVSEID().get_selection()) {
single_value->field_EVSEID = other_value.EVSEID();
} else {
single_value->field_EVSEID.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EVSETimeStamp().get_selection()) {
single_value->field_EVSETimeStamp = other_value.EVSETimeStamp();
} else {
single_value->field_EVSETimeStamp.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new SessionSetupRes_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.SessionSetupRes.");
break;
}
set_selection(other_value);
}

