boolean ServiceDiscoveryReq_template::match(const ServiceDiscoveryReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.ServiceScope().is_bound()) return FALSE;
if((other_value.ServiceScope().ispresent() ? !single_value->field_ServiceScope.match((const CHARSTRING&)other_value.ServiceScope(), legacy) : !single_value->field_ServiceScope.match_omit(legacy)))return FALSE;
if(!other_value.ServiceType().is_bound()) return FALSE;
if((other_value.ServiceType().ispresent() ? !single_value->field_ServiceType.match((const INTEGER&)other_value.ServiceType(), legacy) : !single_value->field_ServiceType.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.ServiceDiscoveryReq.");
}
return FALSE;
}

