void CableCheckReq_template::copy_value(const CableCheckReq& other_value)
{
single_value = new single_value_struct;
if (other_value.dummy().is_bound()) {
  if (other_value.dummy().ispresent()) single_value->field_dummy = other_value.dummy()();
  else single_value->field_dummy = OMIT_VALUE;
} else {
  single_value->field_dummy.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void CableCheckReq_template::copy_template(const CableCheckReq_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.dummy().get_selection()) {
single_value->field_dummy = other_value.dummy();
} else {
single_value->field_dummy.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new CableCheckReq_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.CableCheckReq.");
break;
}
set_selection(other_value);
}

