  if (other_value.ResponseCode().is_bound()) field_ResponseCode = other_value.ResponseCode();
  else field_ResponseCode.clean_up();
  if (other_value.EVSEProcessing().is_bound()) field_EVSEProcessing = other_value.EVSEProcessing();
  else field_EVSEProcessing.clean_up();
