void ChargeParameterDiscoveryReq_template::log_match(const ChargeParameterDiscoveryReq& match_value, boolean legacy) const
{
if(TTCN_Logger::VERBOSITY_COMPACT == TTCN_Logger::get_matching_verbosity()){
if(match(match_value, legacy)){
TTCN_Logger::print_logmatch_buffer();
TTCN_Logger::log_event_str(" matched");
} else{
if (template_selection == SPECIFIC_VALUE) {
size_t previous_size = TTCN_Logger::get_logmatch_buffer_len();
if (match_value.MaxEntriesSAScheduleTuple().ispresent()){
if(!single_value->field_MaxEntriesSAScheduleTuple.match(match_value.MaxEntriesSAScheduleTuple(), legacy)){
TTCN_Logger::log_logmatch_info(".MaxEntriesSAScheduleTuple");
single_value->field_MaxEntriesSAScheduleTuple.log_match(match_value.MaxEntriesSAScheduleTuple(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
} else {
if (!single_value->field_MaxEntriesSAScheduleTuple.match_omit(legacy)){
 TTCN_Logger::log_logmatch_info(".MaxEntriesSAScheduleTuple := omit with ");
TTCN_Logger::print_logmatch_buffer();
single_value->field_MaxEntriesSAScheduleTuple.log();
TTCN_Logger::log_event_str(" unmatched");
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}
if (match_value.EnergyTransferType().ispresent()){
if(!single_value->field_EnergyTransferType.match(match_value.EnergyTransferType(), legacy)){
TTCN_Logger::log_logmatch_info(".EnergyTransferType");
single_value->field_EnergyTransferType.log_match(match_value.EnergyTransferType(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
} else {
if (!single_value->field_EnergyTransferType.match_omit(legacy)){
 TTCN_Logger::log_logmatch_info(".EnergyTransferType := omit with ");
TTCN_Logger::print_logmatch_buffer();
single_value->field_EnergyTransferType.log();
TTCN_Logger::log_event_str(" unmatched");
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}
}else {
TTCN_Logger::print_logmatch_buffer();
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
TTCN_Logger::log_event_str(" unmatched");
}
}
return;
}
if (template_selection == SPECIFIC_VALUE) {
TTCN_Logger::log_event_str("{ MaxEntriesSAScheduleTuple := ");
if (match_value.MaxEntriesSAScheduleTuple().ispresent()) single_value->field_MaxEntriesSAScheduleTuple.log_match(match_value.MaxEntriesSAScheduleTuple(), legacy);
else {
TTCN_Logger::log_event_str("omit with ");
single_value->field_MaxEntriesSAScheduleTuple.log();
if (single_value->field_MaxEntriesSAScheduleTuple.match_omit(legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
TTCN_Logger::log_event_str(", EnergyTransferType := ");
if (match_value.EnergyTransferType().ispresent()) single_value->field_EnergyTransferType.log_match(match_value.EnergyTransferType(), legacy);
else {
TTCN_Logger::log_event_str("omit with ");
single_value->field_EnergyTransferType.log();
if (single_value->field_EnergyTransferType.match_omit(legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
TTCN_Logger::log_event_str(" }");
} else {
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
if (match(match_value, legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
}

