void PowerDeliveryReq_template::log_match(const PowerDeliveryReq& match_value, boolean legacy) const
{
if(TTCN_Logger::VERBOSITY_COMPACT == TTCN_Logger::get_matching_verbosity()){
if(match(match_value, legacy)){
TTCN_Logger::print_logmatch_buffer();
TTCN_Logger::log_event_str(" matched");
} else{
if (template_selection == SPECIFIC_VALUE) {
size_t previous_size = TTCN_Logger::get_logmatch_buffer_len();
if(!single_value->field_ChargeProgress.match(match_value.ChargeProgress(), legacy)){
TTCN_Logger::log_logmatch_info(".ChargeProgress");
single_value->field_ChargeProgress.log_match(match_value.ChargeProgress(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
if(!single_value->field_SAScheduleTupleID.match(match_value.SAScheduleTupleID(), legacy)){
TTCN_Logger::log_logmatch_info(".SAScheduleTupleID");
single_value->field_SAScheduleTupleID.log_match(match_value.SAScheduleTupleID(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}else {
TTCN_Logger::print_logmatch_buffer();
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
TTCN_Logger::log_event_str(" unmatched");
}
}
return;
}
if (template_selection == SPECIFIC_VALUE) {
TTCN_Logger::log_event_str("{ ChargeProgress := ");
single_value->field_ChargeProgress.log_match(match_value.ChargeProgress(), legacy);
TTCN_Logger::log_event_str(", SAScheduleTupleID := ");
single_value->field_SAScheduleTupleID.log_match(match_value.SAScheduleTupleID(), legacy);
TTCN_Logger::log_event_str(" }");
} else {
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
if (match(match_value, legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
}

