struct PaymentDetailsReq_template::single_value_struct {
CHARSTRING_template field_EVCertificate;
OCTETSTRING_template field_EVCCID;
};

void PaymentDetailsReq_template::set_specific()
{
if (template_selection != SPECIFIC_VALUE) {
template_sel old_selection = template_selection;
clean_up();
single_value = new single_value_struct;
set_selection(SPECIFIC_VALUE);
if (old_selection == ANY_VALUE || old_selection == ANY_OR_OMIT) {
single_value->field_EVCertificate = ANY_OR_OMIT;
single_value->field_EVCCID = ANY_OR_OMIT;
}
}
}

void PaymentDetailsReq_template::copy_value(const PaymentDetailsReq& other_value)
{
single_value = new single_value_struct;
if (other_value.EVCertificate().is_bound()) {
  if (other_value.EVCertificate().ispresent()) single_value->field_EVCertificate = other_value.EVCertificate()();
  else single_value->field_EVCertificate = OMIT_VALUE;
} else {
  single_value->field_EVCertificate.clean_up();
}
if (other_value.EVCCID().is_bound()) {
  if (other_value.EVCCID().ispresent()) single_value->field_EVCCID = other_value.EVCCID()();
  else single_value->field_EVCCID = OMIT_VALUE;
} else {
  single_value->field_EVCCID.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void PaymentDetailsReq_template::copy_template(const PaymentDetailsReq_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.EVCertificate().get_selection()) {
single_value->field_EVCertificate = other_value.EVCertificate();
} else {
single_value->field_EVCertificate.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EVCCID().get_selection()) {
single_value->field_EVCCID = other_value.EVCCID();
} else {
single_value->field_EVCCID.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new PaymentDetailsReq_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.PaymentDetailsReq.");
break;
}
set_selection(other_value);
}

