boolean PaymentDetailsReq_template::match(const PaymentDetailsReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.EVCertificate().is_bound()) return FALSE;
if((other_value.EVCertificate().ispresent() ? !single_value->field_EVCertificate.match((const CHARSTRING&)other_value.EVCertificate(), legacy) : !single_value->field_EVCertificate.match_omit(legacy)))return FALSE;
if(!other_value.EVCCID().is_bound()) return FALSE;
if((other_value.EVCCID().ispresent() ? !single_value->field_EVCCID.match((const OCTETSTRING&)other_value.EVCCID(), legacy) : !single_value->field_EVCCID.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.PaymentDetailsReq.");
}
return FALSE;
}

boolean PaymentDetailsReq_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return (single_value->field_EVCertificate.is_omit() || single_value->field_EVCertificate.is_bound())

 ||(single_value->field_EVCCID.is_omit() || single_value->field_EVCCID.is_bound())
;
}

boolean PaymentDetailsReq_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return (single_value->field_EVCertificate.is_omit() || single_value->field_EVCertificate.is_value())
 &&(single_value->field_EVCCID.is_omit() || single_value->field_EVCCID.is_value());
}

void PaymentDetailsReq_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

PaymentDetailsReq PaymentDetailsReq_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.PaymentDetailsReq.");
PaymentDetailsReq ret_val;
if (single_value->field_EVCertificate.is_omit()) ret_val.EVCertificate() = OMIT_VALUE;
else if (single_value->field_EVCertificate.is_bound()) {
ret_val.EVCertificate() = single_value->field_EVCertificate.valueof();
}
if (single_value->field_EVCCID.is_omit()) ret_val.EVCCID() = OMIT_VALUE;
else if (single_value->field_EVCCID.is_bound()) {
ret_val.EVCCID() = single_value->field_EVCCID.valueof();
}
return ret_val;
}

