struct PaymentDetailsRes_template::single_value_struct {
INTEGER_template field_ResponseCode;
CHARSTRING_template field_SelectedPaymentOption;
CHARSTRING_template field_EMAID;
};

void PaymentDetailsRes_template::set_specific()
{
if (template_selection != SPECIFIC_VALUE) {
template_sel old_selection = template_selection;
clean_up();
single_value = new single_value_struct;
set_selection(SPECIFIC_VALUE);
if (old_selection == ANY_VALUE || old_selection == ANY_OR_OMIT) {
single_value->field_ResponseCode = ANY_VALUE;
single_value->field_SelectedPaymentOption = ANY_OR_OMIT;
single_value->field_EMAID = ANY_OR_OMIT;
}
}
}

void PaymentDetailsRes_template::copy_value(const PaymentDetailsRes& other_value)
{
single_value = new single_value_struct;
if (other_value.ResponseCode().is_bound()) {
  single_value->field_ResponseCode = other_value.ResponseCode();
} else {
  single_value->field_ResponseCode.clean_up();
}
if (other_value.SelectedPaymentOption().is_bound()) {
  if (other_value.SelectedPaymentOption().ispresent()) single_value->field_SelectedPaymentOption = other_value.SelectedPaymentOption()();
  else single_value->field_SelectedPaymentOption = OMIT_VALUE;
} else {
  single_value->field_SelectedPaymentOption.clean_up();
}
if (other_value.EMAID().is_bound()) {
  if (other_value.EMAID().ispresent()) single_value->field_EMAID = other_value.EMAID()();
  else single_value->field_EMAID = OMIT_VALUE;
} else {
  single_value->field_EMAID.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void PaymentDetailsRes_template::copy_template(const PaymentDetailsRes_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.ResponseCode().get_selection()) {
single_value->field_ResponseCode = other_value.ResponseCode();
} else {
single_value->field_ResponseCode.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.SelectedPaymentOption().get_selection()) {
single_value->field_SelectedPaymentOption = other_value.SelectedPaymentOption();
} else {
single_value->field_SelectedPaymentOption.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EMAID().get_selection()) {
single_value->field_EMAID = other_value.EMAID();
} else {
single_value->field_EMAID.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new PaymentDetailsRes_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.PaymentDetailsRes.");
break;
}
set_selection(other_value);
}

