void PreChargeReq_template::copy_value(const PreChargeReq& other_value)
{
single_value = new single_value_struct;
if (other_value.TargetVoltage().is_bound()) {
  if (other_value.TargetVoltage().ispresent()) single_value->field_TargetVoltage = other_value.TargetVoltage()();
  else single_value->field_TargetVoltage = OMIT_VALUE;
} else {
  single_value->field_TargetVoltage.clean_up();
}
if (other_value.TargetCurrent().is_bound()) {
  if (other_value.TargetCurrent().ispresent()) single_value->field_TargetCurrent = other_value.TargetCurrent()();
  else single_value->field_TargetCurrent = OMIT_VALUE;
} else {
  single_value->field_TargetCurrent.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void PreChargeReq_template::copy_template(const PreChargeReq_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.TargetVoltage().get_selection()) {
single_value->field_TargetVoltage = other_value.TargetVoltage();
} else {
single_value->field_TargetVoltage.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.TargetCurrent().get_selection()) {
single_value->field_TargetCurrent = other_value.TargetCurrent();
} else {
single_value->field_TargetCurrent.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new PreChargeReq_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.PreChargeReq.");
break;
}
set_selection(other_value);
}

