{
}

PreChargeReq_template::PreChargeReq_template(template_sel other_value)
 : Base_Template(other_value)
{
check_single_selection(other_value);
}

PreChargeReq_template::PreChargeReq_template(const PreChargeReq& other_value)
{
copy_value(other_value);
}

PreChargeReq_template::PreChargeReq_template(const OPTIONAL<PreChargeReq>& other_value)
{
switch (other_value.get_selection()) {
case OPTIONAL_PRESENT:
copy_value((const PreChargeReq&)other_value);
break;
case OPTIONAL_OMIT:
set_selection(OMIT_VALUE);
break;
default:
TTCN_error("Creating a template of type @SECC_Types.PreChargeReq from an unbound optional field.");
}
}

PreChargeReq_template::PreChargeReq_template(const PreChargeReq_template& other_value)
: Base_Template()
{
copy_template(other_value);
}

PreChargeReq_template::~PreChargeReq_template()
{
clean_up();
}

PreChargeReq_template& PreChargeReq_template::operator=(template_sel other_value)
{
check_single_selection(other_value);
clean_up();
set_selection(other_value);
return *this;
}

PreChargeReq_template& PreChargeReq_template::operator=(const PreChargeReq& other_value)
{
clean_up();
copy_value(other_value);
return *this;
}

PreChargeReq_template& PreChargeReq_template::operator=(const OPTIONAL<PreChargeReq>& other_value)
{
clean_up();
switch (other_value.get_selection()) {
case OPTIONAL_PRESENT:
copy_value((const PreChargeReq&)other_value);
break;
case OPTIONAL_OMIT:
set_selection(OMIT_VALUE);
break;
default:
TTCN_error("Assignment of an unbound optional field to a template of type @SECC_Types.PreChargeReq.");
}
return *this;
}

PreChargeReq_template& PreChargeReq_template::operator=(const PreChargeReq_template& other_value)
{
if (&other_value != this) {
clean_up();
copy_template(other_value);
}
return *this;
}

boolean PreChargeReq_template::match(const PreChargeReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.TargetVoltage().is_bound()) return FALSE;
if((other_value.TargetVoltage().ispresent() ? !single_value->field_TargetVoltage.match((const INTEGER&)other_value.TargetVoltage(), legacy) : !single_value->field_TargetVoltage.match_omit(legacy)))return FALSE;
if(!other_value.TargetCurrent().is_bound()) return FALSE;
if((other_value.TargetCurrent().ispresent() ? !single_value->field_TargetCurrent.match((const INTEGER&)other_value.TargetCurrent(), legacy) : !single_value->field_TargetCurrent.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.PreChargeReq.");
}
return FALSE;
}

boolean PreChargeReq_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return (single_value->field_TargetVoltage.is_omit() || single_value->field_TargetVoltage.is_bound())

 ||(single_value->field_TargetCurrent.is_omit() || single_value->field_TargetCurrent.is_bound())
;
}

boolean PreChargeReq_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return (single_value->field_TargetVoltage.is_omit() || single_value->field_TargetVoltage.is_value())
 &&(single_value->field_TargetCurrent.is_omit() || single_value->field_TargetCurrent.is_value());
}

void PreChargeReq_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

PreChargeReq PreChargeReq_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.PreChargeReq.");
PreChargeReq ret_val;
if (single_value->field_TargetVoltage.is_omit()) ret_val.TargetVoltage() = OMIT_VALUE;
else if (single_value->field_TargetVoltage.is_bound()) {
ret_val.TargetVoltage() = single_value->field_TargetVoltage.valueof();
}
if (single_value->field_TargetCurrent.is_omit()) ret_val.TargetCurrent() = OMIT_VALUE;
else if (single_value->field_TargetCurrent.is_bound()) {
ret_val.TargetCurrent() = single_value->field_TargetCurrent.valueof();
}
return ret_val;
}

void PreChargeReq_template::set_type(template_sel template_type, unsigned int list_length)
{
if (template_type != VALUE_LIST && template_type != COMPLEMENTED_LIST)
TTCN_error("Setting an invalid list for a template of type @SECC_Types.PreChargeReq.");
clean_up();
set_selection(template_type);
value_list.n_values = list_length;
value_list.list_value = new PreChargeReq_template[list_length];
}

PreChargeReq_template& PreChargeReq_template::list_item(unsigned int list_index) const
{
if (template_selection != VALUE_LIST && template_selection != COMPLEMENTED_LIST)
TTCN_error("Accessing a list element of a non-list template of type @SECC_Types.PreChargeReq.");
if (list_index >= value_list.n_values)
TTCN_error("Index overflow in a value list template of type @SECC_Types.PreChargeReq.");
return value_list.list_value[list_index];
}

