boolean PreChargeRes_template::match(const PreChargeRes& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.ResponseCode().is_bound()) return FALSE;
if(!single_value->field_ResponseCode.match(other_value.ResponseCode(), legacy))return FALSE;
if(!other_value.EVSEProcessing().is_bound()) return FALSE;
if((other_value.EVSEProcessing().ispresent() ? !single_value->field_EVSEProcessing.match((const INTEGER&)other_value.EVSEProcessing(), legacy) : !single_value->field_EVSEProcessing.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.PreChargeRes.");
}
return FALSE;
}

boolean PreChargeRes_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return single_value->field_ResponseCode.is_bound()

 ||(single_value->field_EVSEProcessing.is_omit() || single_value->field_EVSEProcessing.is_bound())
;
}

boolean PreChargeRes_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return single_value->field_ResponseCode.is_value()
 &&(single_value->field_EVSEProcessing.is_omit() || single_value->field_EVSEProcessing.is_value());
}

void PreChargeRes_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

PreChargeRes PreChargeRes_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.PreChargeRes.");
PreChargeRes ret_val;
if (single_value->field_ResponseCode.is_bound()) {
ret_val.ResponseCode() = single_value->field_ResponseCode.valueof();
}
if (single_value->field_EVSEProcessing.is_omit()) ret_val.EVSEProcessing() = OMIT_VALUE;
else if (single_value->field_EVSEProcessing.is_bound()) {
ret_val.EVSEProcessing() = single_value->field_EVSEProcessing.valueof();
}
return ret_val;
}

