boolean CurrentDemandReq_template::match(const CurrentDemandReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.TargetVoltage().is_bound()) return FALSE;
if((other_value.TargetVoltage().ispresent() ? !single_value->field_TargetVoltage.match((const INTEGER&)other_value.TargetVoltage(), legacy) : !single_value->field_TargetVoltage.match_omit(legacy)))return FALSE;
if(!other_value.TargetCurrent().is_bound()) return FALSE;
if((other_value.TargetCurrent().ispresent() ? !single_value->field_TargetCurrent.match((const INTEGER&)other_value.TargetCurrent(), legacy) : !single_value->field_TargetCurrent.match_omit(legacy)))return FALSE;
if(!other_value.TargetPower().is_bound()) return FALSE;
if((other_value.TargetPower().ispresent() ? !single_value->field_TargetPower.match((const INTEGER&)other_value.TargetPower(), legacy) : !single_value->field_TargetPower.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.CurrentDemandReq.");
}
return FALSE;
}

boolean CurrentDemandReq_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return (single_value->field_TargetVoltage.is_omit() || single_value->field_TargetVoltage.is_bound())

 ||(single_value->field_TargetCurrent.is_omit() || single_value->field_TargetCurrent.is_bound())

 ||(single_value->field_TargetPower.is_omit() || single_value->field_TargetPower.is_bound())
;
}

boolean CurrentDemandReq_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return (single_value->field_TargetVoltage.is_omit() || single_value->field_TargetVoltage.is_value())
 &&(single_value->field_TargetCurrent.is_omit() || single_value->field_TargetCurrent.is_value())
 &&(single_value->field_TargetPower.is_omit() || single_value->field_TargetPower.is_value());
}

void CurrentDemandReq_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

CurrentDemandReq CurrentDemandReq_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.CurrentDemandReq.");
CurrentDemandReq ret_val;
if (single_value->field_TargetVoltage.is_omit()) ret_val.TargetVoltage() = OMIT_VALUE;
else if (single_value->field_TargetVoltage.is_bound()) {
ret_val.TargetVoltage() = single_value->field_TargetVoltage.valueof();
}
if (single_value->field_TargetCurrent.is_omit()) ret_val.TargetCurrent() = OMIT_VALUE;
else if (single_value->field_TargetCurrent.is_bound()) {
ret_val.TargetCurrent() = single_value->field_TargetCurrent.valueof();
}
if (single_value->field_TargetPower.is_omit()) ret_val.TargetPower() = OMIT_VALUE;
else if (single_value->field_TargetPower.is_bound()) {
ret_val.TargetPower() = single_value->field_TargetPower.valueof();
}
return ret_val;
}

