void CurrentDemandRes_template::copy_value(const CurrentDemandRes& other_value)
{
single_value = new single_value_struct;
if (other_value.ResponseCode().is_bound()) {
  single_value->field_ResponseCode = other_value.ResponseCode();
} else {
  single_value->field_ResponseCode.clean_up();
}
if (other_value.EVSEProcessing().is_bound()) {
  if (other_value.EVSEProcessing().ispresent()) single_value->field_EVSEProcessing = other_value.EVSEProcessing()();
  else single_value->field_EVSEProcessing = OMIT_VALUE;
} else {
  single_value->field_EVSEProcessing.clean_up();
}
if (other_value.EVSEVoltage().is_bound()) {
  if (other_value.EVSEVoltage().ispresent()) single_value->field_EVSEVoltage = other_value.EVSEVoltage()();
  else single_value->field_EVSEVoltage = OMIT_VALUE;
} else {
  single_value->field_EVSEVoltage.clean_up();
}
if (other_value.EVSECurrent().is_bound()) {
  if (other_value.EVSECurrent().ispresent()) single_value->field_EVSECurrent = other_value.EVSECurrent()();
  else single_value->field_EVSECurrent = OMIT_VALUE;
} else {
  single_value->field_EVSECurrent.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void CurrentDemandRes_template::copy_template(const CurrentDemandRes_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.ResponseCode().get_selection()) {
single_value->field_ResponseCode = other_value.ResponseCode();
} else {
single_value->field_ResponseCode.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EVSEProcessing().get_selection()) {
single_value->field_EVSEProcessing = other_value.EVSEProcessing();
} else {
single_value->field_EVSEProcessing.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EVSEVoltage().get_selection()) {
single_value->field_EVSEVoltage = other_value.EVSEVoltage();
} else {
single_value->field_EVSEVoltage.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.EVSECurrent().get_selection()) {
single_value->field_EVSECurrent = other_value.EVSECurrent();
} else {
single_value->field_EVSECurrent.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new CurrentDemandRes_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.CurrentDemandRes.");
break;
}
set_selection(other_value);
}

