boolean CurrentDemandRes_template::match(const CurrentDemandRes& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.ResponseCode().is_bound()) return FALSE;
if(!single_value->field_ResponseCode.match(other_value.ResponseCode(), legacy))return FALSE;
if(!other_value.EVSEProcessing().is_bound()) return FALSE;
if((other_value.EVSEProcessing().ispresent() ? !single_value->field_EVSEProcessing.match((const INTEGER&)other_value.EVSEProcessing(), legacy) : !single_value->field_EVSEProcessing.match_omit(legacy)))return FALSE;
if(!other_value.EVSEVoltage().is_bound()) return FALSE;
if((other_value.EVSEVoltage().ispresent() ? !single_value->field_EVSEVoltage.match((const INTEGER&)other_value.EVSEVoltage(), legacy) : !single_value->field_EVSEVoltage.match_omit(legacy)))return FALSE;
if(!other_value.EVSECurrent().is_bound()) return FALSE;
if((other_value.EVSECurrent().ispresent() ? !single_value->field_EVSECurrent.match((const INTEGER&)other_value.EVSECurrent(), legacy) : !single_value->field_EVSECurrent.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.CurrentDemandRes.");
}
return FALSE;
}

boolean CurrentDemandRes_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return single_value->field_ResponseCode.is_bound()

 ||(single_value->field_EVSEProcessing.is_omit() || single_value->field_EVSEProcessing.is_bound())

 ||(single_value->field_EVSEVoltage.is_omit() || single_value->field_EVSEVoltage.is_bound())

 ||(single_value->field_EVSECurrent.is_omit() || single_value->field_EVSECurrent.is_bound())
;
}

boolean CurrentDemandRes_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return single_value->field_ResponseCode.is_value()
 &&(single_value->field_EVSEProcessing.is_omit() || single_value->field_EVSEProcessing.is_value())
 &&(single_value->field_EVSEVoltage.is_omit() || single_value->field_EVSEVoltage.is_value())
 &&(single_value->field_EVSECurrent.is_omit() || single_value->field_EVSECurrent.is_value());
}

void CurrentDemandRes_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

CurrentDemandRes CurrentDemandRes_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.CurrentDemandRes.");
CurrentDemandRes ret_val;
if (single_value->field_ResponseCode.is_bound()) {
ret_val.ResponseCode() = single_value->field_ResponseCode.valueof();
}
if (single_value->field_EVSEProcessing.is_omit()) ret_val.EVSEProcessing() = OMIT_VALUE;
else if (single_value->field_EVSEProcessing.is_bound()) {
ret_val.EVSEProcessing() = single_value->field_EVSEProcessing.valueof();
}
if (single_value->field_EVSEVoltage.is_omit()) ret_val.EVSEVoltage() = OMIT_VALUE;
else if (single_value->field_EVSEVoltage.is_bound()) {
ret_val.EVSEVoltage() = single_value->field_EVSEVoltage.valueof();
}
if (single_value->field_EVSECurrent.is_omit()) ret_val.EVSECurrent() = OMIT_VALUE;
else if (single_value->field_EVSECurrent.is_bound()) {
ret_val.EVSECurrent() = single_value->field_EVSECurrent.valueof();
}
return ret_val;
}

