void MeterReceiptReq_template::copy_value(const MeterReceiptReq& other_value)
{
single_value = new single_value_struct;
if (other_value.ResponseCode().is_bound()) {
  if (other_value.ResponseCode().ispresent()) single_value->field_ResponseCode = other_value.ResponseCode()();
  else single_value->field_ResponseCode = OMIT_VALUE;
} else {
  single_value->field_ResponseCode.clean_up();
}
if (other_value.MeteringSignature().is_bound()) {
  if (other_value.MeteringSignature().ispresent()) single_value->field_MeteringSignature = other_value.MeteringSignature()();
  else single_value->field_MeteringSignature = OMIT_VALUE;
} else {
  single_value->field_MeteringSignature.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void MeterReceiptReq_template::copy_template(const MeterReceiptReq_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.ResponseCode().get_selection()) {
single_value->field_ResponseCode = other_value.ResponseCode();
} else {
single_value->field_ResponseCode.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.MeteringSignature().get_selection()) {
single_value->field_MeteringSignature = other_value.MeteringSignature();
} else {
single_value->field_MeteringSignature.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new MeterReceiptReq_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.MeterReceiptReq.");
break;
}
set_selection(other_value);
}

