boolean CertificateInstallationRes_template::match(const CertificateInstallationRes& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.ResponseCode().is_bound()) return FALSE;
if(!single_value->field_ResponseCode.match(other_value.ResponseCode(), legacy))return FALSE;
if(!other_value.ContractSignatureCertChain().is_bound()) return FALSE;
if((other_value.ContractSignatureCertChain().ispresent() ? !single_value->field_ContractSignatureCertChain.match((const OCTETSTRING&)other_value.ContractSignatureCertChain(), legacy) : !single_value->field_ContractSignatureCertChain.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.CertificateInstallationRes.");
}
return FALSE;
}

