struct ServiceDetailsReq_template::single_value_struct {
INTEGER_template field_ServiceID;
CHARSTRING_template field_ServiceScope;
};

void ServiceDetailsReq_template::set_specific()
{
if (template_selection != SPECIFIC_VALUE) {
template_sel old_selection = template_selection;
clean_up();
single_value = new single_value_struct;
set_selection(SPECIFIC_VALUE);
if (old_selection == ANY_VALUE || old_selection == ANY_OR_OMIT) {
single_value->field_ServiceID = ANY_OR_OMIT;
single_value->field_ServiceScope = ANY_OR_OMIT;
}
}
}

void ServiceDetailsReq_template::copy_value(const ServiceDetailsReq& other_value)
{
single_value = new single_value_struct;
if (other_value.ServiceID().is_bound()) {
  if (other_value.ServiceID().ispresent()) single_value->field_ServiceID = other_value.ServiceID()();
  else single_value->field_ServiceID = OMIT_VALUE;
} else {
  single_value->field_ServiceID.clean_up();
}
if (other_value.ServiceScope().is_bound()) {
  if (other_value.ServiceScope().ispresent()) single_value->field_ServiceScope = other_value.ServiceScope()();
  else single_value->field_ServiceScope = OMIT_VALUE;
} else {
  single_value->field_ServiceScope.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void ServiceDetailsReq_template::copy_template(const ServiceDetailsReq_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.ServiceID().get_selection()) {
single_value->field_ServiceID = other_value.ServiceID();
} else {
single_value->field_ServiceID.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.ServiceScope().get_selection()) {
single_value->field_ServiceScope = other_value.ServiceScope();
} else {
single_value->field_ServiceScope.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new ServiceDetailsReq_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.ServiceDetailsReq.");
break;
}
set_selection(other_value);
}

