boolean ServiceDetailsReq_template::match(const ServiceDetailsReq& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.ServiceID().is_bound()) return FALSE;
if((other_value.ServiceID().ispresent() ? !single_value->field_ServiceID.match((const INTEGER&)other_value.ServiceID(), legacy) : !single_value->field_ServiceID.match_omit(legacy)))return FALSE;
if(!other_value.ServiceScope().is_bound()) return FALSE;
if((other_value.ServiceScope().ispresent() ? !single_value->field_ServiceScope.match((const CHARSTRING&)other_value.ServiceScope(), legacy) : !single_value->field_ServiceScope.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.ServiceDetailsReq.");
}
return FALSE;
}

boolean ServiceDetailsReq_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return (single_value->field_ServiceID.is_omit() || single_value->field_ServiceID.is_bound())

 ||(single_value->field_ServiceScope.is_omit() || single_value->field_ServiceScope.is_bound())
;
}

boolean ServiceDetailsReq_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return (single_value->field_ServiceID.is_omit() || single_value->field_ServiceID.is_value())
 &&(single_value->field_ServiceScope.is_omit() || single_value->field_ServiceScope.is_value());
}

void ServiceDetailsReq_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

